  [428238] = { nil, "Sopravvivi al rituale.", nil, 0x0bd96c0c, "mu" },
  [428482] = { nil, "Salute massima ridotta del $N1% e danni da ombra subiti aumentati del $N2%.", nil, 0xde95b958, "mu" },
