  [428489] = { "Entra per un istante in un altro piano dell'esistenza, riducendo all'istante la minaccia e riducendo del $N1% tutti i danni subiti e inflitti per $D1.", "Il tuo corpo fisico è entrato in un altro piano dell'esistenza. Tutti i danni subiti e inflitti sono ridotti.", 0x0d5e0c0d, 0x3e633c66, "uu" },
