  [428604] = { "Piazza la bestiola come esca.", nil, 0x9480a4db, nil, "um" },
  [428708] = { "Converte risorse in salute ogni secondo per $D1. Ogni secondo vengono convertiti fino a $N2 rabbia, $N3 energia o il $N4% del mana base in un massimo del $N5% della salute.", "Conversione delle risorse in salute.", 0x60a09161, 0x1bfa0d3b, "uu" },
  [428710] = { nil, "La magia che vincola l'elementale si sta sciogliendo e irradia mana grezzo sui giocatori vicini.", nil, 0xd7aae66f, "mu" },
  [428713] = { "La pelle del bersaglio diventa dura come la corteccia. Danni fisici subiti ridotti del $N1%. Mentre la protezione è attiva, gli attacchi che infliggono danni non ritardano il lancio degli incantesimi. Dura $D1.", "Danni fisici subiti ridotti del $N1%. Mentre la protezione è attiva, gli attacchi che infliggono danni non ritardano il lancio degli incantesimi.", 0xa3962e6a, 0x94e200c6, "uu" },
  [428717] = { "Aumenta del $N1% i danni inflitti da ⟦Explosive Shot=Tiro Esplosivo⟧ e da tutte le tue trappole che infliggono danni. Inoltre, i danni iniziali di ⟦Explosive Trap=Trappola Esplosiva⟧ e i danni periodici totali di ⟦Immolation Trap=Trappola Incendiaria⟧ aumentano di un ammontare pari al $N2% della tua potenza d'attacco in mischia o a distanza.", nil, 0x41837b4a, nil, "um" },
  [428726] = { "Consuma tutte le applicazioni di Frenesia del tuo famiglio, aumentando la tua velocità d'attacco a distanza del $N1% e fornendo al famiglio $N2 Focus per ogni applicazione di Frenesia consumata. Dura $D1.\n\nIl tuo famiglio ottiene Frenesia ogni volta che usa un attacco base, che aumenta la sua velocità d'attacco in mischia del $N4% per $D2, cumulabile fino a $N6 volte.", "Aumenta la velocità d'attacco a distanza del $N1%.", 0x822ef164, 0x3092f5a5, "uu" },
  [428728] = { "Aumenta del $N1% la velocità d'attacco in mischia del famiglio per $D1.", "Aumenta la velocità d'attacco in mischia del famiglio del $N1%.", 0xc2205de3, 0x389c7132, "uu" },
  [428733] = { nil, "Le acque corrotte ti si aggrappano addosso.", nil, 0xc24bd8e8, "mu" },
  [428738] = { "Aumenta del $N1% l'efficacia dei tuoi incantesimi ⟦Mana Shield=Scudo di Mana⟧, ⟦Frost Ward=Protezione dal Gelo⟧ e ⟦Fire Ward=Guardia di Fuoco⟧ e riduce del $N2% il mana consumato da ⟦Mana Shield=Scudo di Mana⟧ per ogni punto di danno.", nil, 0x407137e1, nil, "um" },
  [428739] = { "Stordisce il bersaglio per $D1. Utilizzabile solo su bersagli congelati. Infligge $N2 danni ai bersagli immuni in modo permanente allo stordimento. Questi danni beneficiano delle applicazioni di Glaciazione, senza consumarle.", "Stordito e congelato.", 0x477daf2a, 0xf27e935d, "uu" },
  [428741] = { "Infligge $N1 danni da fuoco quando vieni colpito, aumenta del $N2% la tua probabilità di critico con gli incantesimi e riduce del $N3% la probabilità di subire colpi critici. Sul Mago può essere attivo un solo tipo di incantesimo di armatura alla volta. Dura $D1.", "Infligge danni da fuoco a chi ti attacca. Probabilità di subire colpi critici ridotta del $N1%. Probabilità di critico con gli incantesimi aumentata del $N2%.", 0x27550fe0, 0x870914a3, "uu" },
