  [428863] = { "Ottieni l'abilità Dislocazione:\n\n$I1\nTi teletrasporta nel punto in cui hai lanciato Traslazione l'ultima volta e azzera il tempo di recupero di Traslazione. Utilizzabile solo entro $D1 dal lancio di Traslazione.", nil, 0x0e540e26, nil, "um" },
