  [428878] = { "Scatena contro il nemico un'esplosione di magia pura che distorce la realtà, infliggendo $N1 danni chimerici.\n\nAumenta del $N2% i danni di Balefire Bolt e Pirosfera e riduce del $N3% il tuo Spirito, effetto cumulabile fino a $N4 volte per $D1. Se il tuo Spirito scende a $N6, muori.\n\nQuesto incantesimo viene confrontato con la più bassa tra le resistenze del bersaglio all'arcano, al fuoco e al gelo.", "Aumenta del $N1% i danni inflitti da Balefire Bolt e Pirosfera, ma riduce lo Spirito del $N2%. Arrivare a $N3 Spirito è fatale.", 0x607fa16e, 0xee03cbbc, "uu" },
  [428885] = { "Lancia un globo di energia temporale che avanza lentamente e ogni $D1 fornisce a tutti i membri del gruppo vicini uno scudo che assorbe $N2 danni per $D2. Lo scudo accumula valore aggiuntivo se i membri del gruppo restano vicino al globo.", nil, 0x19333051, nil, "um" },
